Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <map>
#include <cstdio>
using namespace std;

long long ones[20];

// Minimum number of ones that must be used if the largest sumand has at most
// i ones
int count_ones(long long n, int i){
	// Use as many i ones as possible
	int times = i * (n / ones[i]);
	n = n % ones[i];

	// If the number was complete
	if (n == 0) return times;

	// Decide whether to use one more of i ones to the substract or not
	return times +  min( i + count_ones(ones[i] - n, i-1), count_ones(n, i-1));
}

int main() {
	ones[0] = 0;
	for (int i = 1; i <= 16; ++i) ones[i] = ones[i-1] * 10 + 1;

	long long n;
	cin >> n;
	cout << count_ones(n, 16) << endl;

	return 0;
}
